        // Assume 'input' is user input from a web form or URL parameter
        String input = "someUserInput"; // This should be replaced with actual user input

        // Sanitize user input before using it in a command
        if (isValidInput(input)) {
            try {
                Process process = Runtime.getRuntime().exec("echo " + input);
                BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(line);
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        } else {
            System.out.println("Invalid input received.");
        }
    }

